cat > /tmp/probe.pl <<'EOF'
use strict; use warnings;
# probe.pl : args = list of raw W strings (from hex on stdin lines)
# Each stdin line: hex encoding of W.  Prints: hex(W) TAB hex(line10-content)
while (my $l = <STDIN>) {
  chomp $l;
  my $w = pack("H*", $l);
  my $pid = open(my $fh, "-|") or do { exec("/workspace/dataset/test13_executable", $w) or die; };
  local $/; my $out = <$fh>; close($fh);
  $out = "" unless defined $out;
  # find line 10 using markers the-q ... z-test\n
  my $res;
  my $i = index($out, "the-q");
  if ($i >= 0) {
    my $j = index($out, "z-test\n", $i+5);
    if ($j >= 0) { $res = substr($out, $i+5, $j-($i+5)); }
  }
  if (!defined $res) { $res = "??NOMATCH??".$out; }
  print unpack("H*",$l===undef?"":$l), "\t", unpack("H*",$res), "\n";
}
EOF
echo ok

